from itertools import combinations
from math import gcd
import hashlib,json

lo=(2,2,0,0,0); hi=(4,4,4,4,4); ds=list(range(4,21)); hs=(1,2,3,4)
def parts(d):
 out=[]
 def rec(i,prev,rem,a):
  if i==5:
   if rem==0: out.append(tuple(a))
   return
  for x in range(min(prev,hi[i],rem),lo[i]-1,-1): rec(i+1,x,rem-x,a+[x])
 rec(0,4,d,[]); return out
def horiz(a,b):
 # skew horizontal iff interlacing b1>=a1>=b2>=a2...
 return all(b[i]>=a[i] and (i==4 or a[i]>=b[i+1]) for i in range(5))
def smith(A):
 # return nonzero diagonal via elementary integer operations
 A=[r[:] for r in A]; m=len(A); n=len(A[0]) if m else 0; k=0; diag=[]
 def rs(i,j): A[i],A[j]=A[j],A[i]
 def cs(i,j):
  for r in A:A[r][i],A[r][j]=A[r][j],A[r][i]
 while k<m and k<n:
  nz=[(abs(A[i][j]),i,j) for i in range(k,m) for j in range(k,n) if A[i][j]]
  if not nz: break
  _,i,j=min(nz); rs(k,i);cs(k,j)
  while True:
   changed=False
   for i in range(k+1,m):
    if A[i][k]:
     q=A[i][k]//A[k][k]
     for j in range(k,n): A[i][j]-=q*A[k][j]
     if abs(A[i][k])<abs(A[k][k]) and A[i][k]: rs(i,k)
     changed=True;break
   if changed: continue
   for j in range(k+1,n):
    if A[k][j]:
     q=A[k][j]//A[k][k]
     for i in range(k,m): A[i][j]-=q*A[i][k]
     if abs(A[k][j])<abs(A[k][k]) and A[k][j]: cs(j,k)
     changed=True;break
   if changed: continue
   bad=None
   for i in range(k+1,m):
    for j in range(k+1,n):
     if A[i][j]%A[k][k]: bad=(i,j);break
    if bad:break
   if bad:
    i,j=bad
    for r in range(k,m): A[r][k]+=A[r][j]
    continue
   break
  if A[k][k]<0:
   for j in range(k,n):A[k][j]=-A[k][j]
  diag.append(A[k][k]);k+=1
 return diag
res=[]
for d in ds:
 cols=parts(d); idx={x:i for i,x in enumerate(cols)}; rows=[]
 for t in hs:
  for a in parts(d-t) if d-t>=0 else []:
   v=[0]*len(cols)
   for b in cols:
    if horiz(a,b):v[idx[b]]=1
   rows.append({'hDegree':t,'source':list(a),'coefficients':v})
 M=[x['coefficients'] for x in rows]; sd=smith(M) if M else []
 res.append({'degree':d,'columns':[list(x) for x in cols],'rows':rows,'matrixShape':[len(rows),len(cols)],'rank':len(sd),'smithDiagonal':sd,'quotientFreeRank':len(cols)-len(sd),'torsionInvariantFactors':[x for x in sd if x>1]})
out={'input':{'lower':list(lo),'upper':list(hi),'degrees':ds,'hDegrees':list(hs)},'degreeResults':res,'outsideRange':{'degreesBelow4':'zero interval basis and zero quotient','degreesAbove20':'zero interval basis and zero quotient'}}
s=json.dumps(out,separators=(',',':'),sort_keys=True);print(s);print('SHA256',hashlib.sha256(s.encode()).hexdigest())
